# splits on \v, \f, \x1c-\x1e, U+0085, U+2028 and U+2029, which drifts line numbers.
_LINE_SPLIT = re.compile(r"\r\n|\r|\n")
_CENT = Decimal("0.01")
# Amounts may have any number of integer digits, so sums and rounding must not
# be limited by the default 28-digit context: use an effectively unbounded one.
_EXACT = Context(prec=MAX_PREC, Emax=MAX_EMAX, Emin=-MAX_EMAX)


def _fold(category: str) -> str:
    """Normalise a category for comparing, grouping and display.

    ``casefold()`` is used instead of ``lower()`` because it also unifies pairs
    such as ``Straße`` and ``STRASSE``. The result is the displayed name: it is
    still lower case (``Straße`` is shown as ``strasse``).
    """
    return category.casefold()


class ParseError(ValueError):
    """A ledger line is malformed. ``line`` is the 1-based line number."""

    def __init__(self, line: int, reason: str):
        super().__init__("line %d: %s" % (line, reason))
        self.line = line
        self.reason = reason


