class Entry:
    date: date
    category: str
    amount: Decimal
    note: str = ""


def _parse_line(text: str, lineno: int) -> Entry:
    stripped = text.strip()
    parts = _WS_SPLIT.split(stripped, 3)
    if len(parts) < 3:
        raise ParseError(lineno, "expected DATE CATEGORY AMOUNT [NOTE]")
    date_s, category, amount_s = parts[0], parts[1], parts[2]
    note = parts[3].strip() if len(parts) > 3 else ""
    if any(c.isspace() for c in category):
        raise ParseError(lineno, "invalid category %r: must contain no whitespace" % category)
    if not _DATE_RE.match(date_s):
        raise ParseError(lineno, "invalid date %r" % date_s)
    try:
        d = date(int(date_s[:4]), int(date_s[5:7]), int(date_s[8:10]))
    except ValueError:
        raise ParseError(lineno, "invalid date %r" % date_s) from None
    if not _AMOUNT_RE.match(amount_s):
        raise ParseError(lineno, "invalid amount %r" % amount_s)
    return Entry(d, _fold(category), Decimal(amount_s), note)


def parse(text: str) -> List[Entry]:
    """Parse ledger text into entries, in file order.

    One leading UTF-8 byte order mark (U+FEFF) is ignored, as editors on
    Windows often save files with one.
    """
    if text.startswith("\ufeff"):
        text = text[1:]
    entries = []
    for lineno, line in enumerate(_LINE_SPLIT.split(text), 1):
        s = line.strip()
        if not s or s.startswith("#"):
            continue
        entries.append(_parse_line(line, lineno))
    return entries


def balance(entries: Iterable[Entry]) -> Decimal:
    total = Decimal(0)
    for e in entries:
        total = _EXACT.add(total, e.amount)
    return total


def by_category(entries: Iterable[Entry]) -> Dict[str, Decimal]:
    out = {}  # type: Dict[str, Decimal]
    for e in entries:
        out[e.category] = _EXACT.add(out.get(e.category, Decimal(0)), e.amount)
    return out


def by_month(entries: Iterable[Entry]) -> Dict[str, Decimal]:
    out = {}  # type: Dict[str, Decimal]
    for e in entries:
        key = "%04d-%02d" % (e.date.year, e.date.month)
        out[key] = _EXACT.add(out.get(key, Decimal(0)), e.amount)
    return out


def filter_entries(
    entries: Iterable[Entry],
    category: Optional[str] = None,
    since: Optional[date] = None,
    until: Optional[date] = None,
) -> List[Entry]:
    cat = _fold(category) if category is not None else None
    out = []
    for e in entries:
        if cat is not None and _fold(e.category) != cat:
            continue
        if since is not None and e.date < since:
            continue
        if until is not None and e.date > until:
            continue
        out.append(e)
    return out


